CREATE VIEW VW_DOCUMENTIISTANZA AS SELECT 'DOCUMENTI' AS TIPOLOGIA, DOCUMENTIISTANZA.DOCUMENTO AS DESCRIZIONE, DOCUMENTIISTANZA.DATA, DOCUMENTIISTANZA.CODICEOGGETTO, DOCUMENTIISTANZA.STC_IDALLEGATO, DOCUMENTIISTANZA.STC_IDDOCUMENTO, DOCUMENTIISTANZA.CODICEISTANZA, DOCUMENTIISTANZA.IDCOMUNE FROM DOCUMENTIISTANZA UNION 
SELECT 'MOVIMENTI' AS TIPOLOGIA, MOVIMENTIALLEGATI.DESCRIZIONE, MOVIMENTI.DATA, MOVIMENTIALLEGATI.CODICEOGGETTO, MOVIMENTIALLEGATI.STC_IDALLEGATO, MOVIMENTIALLEGATI.STC_IDDOCUMENTO, MOVIMENTI.CODICEISTANZA, MOVIMENTI.IDCOMUNE FROM MOVIMENTI, MOVIMENTIALLEGATI WHERE MOVIMENTIALLEGATI.IDCOMUNE = MOVIMENTI.IDCOMUNE AND MOVIMENTIALLEGATI.CODICEMOVIMENTO = MOVIMENTI.CODICEMOVIMENTO 
UNION 
SELECT 'ENDOPROCEDIMENTI' AS TIPOLOGIA, ISTANZEALLEGATI.ALLEGATOEXTRA AS DESCRIZIONE, ISTANZEPROCEDIMENTI.DATAATTIVAZIONE AS DATA, ISTANZEALLEGATI.CODICEOGGETTO, ISTANZEALLEGATI.STC_IDALLEGATO, ISTANZEALLEGATI.STC_IDDOCUMENTO, ISTANZEALLEGATI.CODICEISTANZA, ISTANZEALLEGATI.IDCOMUNE FROM INVENTARIOPROCEDIMENTI, ISTANZEALLEGATI, ISTANZEPROCEDIMENTI WHERE INVENTARIOPROCEDIMENTI.IDCOMUNE = ISTANZEPROCEDIMENTI.IDCOMUNE AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = ISTANZEPROCEDIMENTI.CODICEINVENTARIO AND ISTANZEPROCEDIMENTI.IDCOMUNE = ISTANZEALLEGATI.IDCOMUNE AND ISTANZEPROCEDIMENTI.CODICEINVENTARIO = ISTANZEALLEGATI.CODICEINVENTARIO AND ISTANZEPROCEDIMENTI.CODICEISTANZA = ISTANZEALLEGATI.CODICEISTANZA;

